-- Administrator metadata only: no account, URL, source text, or secret values.
select jsonb_build_object(
 'capture_rls',(select relrowsecurity from pg_class where oid='public.life_naver_captures'::regclass),
 'private_tables_rls',(select count(*)=6 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='haedo_naver_private' and c.relname in ('inventory','inventory_entries','inventory_seen','capture_jobs','capture_assets','capture_receipts')),
 'capture_owner_policy',exists(select 1 from pg_policies where schemaname='public' and tablename='life_naver_captures' and cmd='SELECT' and roles=array['authenticated']::name[] and qual like '%owner_id%' and qual like '%auth.uid()%'),
 'no_client_capture_write',not has_table_privilege('authenticated','public.life_naver_captures','INSERT,UPDATE,DELETE') and not has_table_privilege('anon','public.life_naver_captures','SELECT,INSERT,UPDATE,DELETE'),
 'private_bucket',exists(select 1 from storage.buckets where id='haedo-naver-originals' and not public and file_size_limit=67108864 and allowed_mime_types=array['image/jpeg','image/png','image/webp']),
 'storage_guards',(select count(*)=4 and bool_and(permissive='RESTRICTIVE') from pg_policies where schemaname='storage' and policyname in ('naver_originals_read_guard','naver_originals_insert_guard','naver_originals_update_guard','naver_originals_delete_guard')),
 'owner_read_api',has_function_privilege('authenticated','public.life_naver_account_list(integer,uuid)','EXECUTE') and has_function_privilege('authenticated','public.life_naver_capture_read(uuid)','EXECUTE') and not has_function_privilege('anon','public.life_naver_account_list(integer,uuid)','EXECUTE'),
 'worker_only_api',has_function_privilege('service_role','public.life_naver_capture_claim(integer,uuid,uuid,uuid)','EXECUTE') and has_function_privilege('service_role','public.life_naver_capture_checkpoint(uuid,uuid,bigint,jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.life_naver_capture_claim(integer,uuid,uuid,uuid)','EXECUTE') and not has_function_privilege('anon','public.life_naver_capture_finish(uuid,uuid,bigint,jsonb,text,text)','EXECUTE'),
 'new_invoker_wrappers',(select count(*)=12 and bool_and(not p.prosecdef and p.proconfig=array['search_path=pg_catalog']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('life_naver_account_list','life_naver_inventory_state','life_naver_inventory_start','life_naver_inventory_list','life_naver_capture_request','life_naver_capture_list','life_naver_capture_read','life_naver_inventory_claim','life_naver_inventory_finish','life_naver_capture_claim','life_naver_capture_finish','life_naver_capture_checkpoint')),
 'owner_cas_http409',position('PT409' in pg_get_functiondef('haedo_naver_private.inventory_start(uuid,bigint)'::regprocedure))>0 and position('PT409' in pg_get_functiondef('haedo_naver_private.capture_request(uuid,text,bigint,boolean)'::regprocedure))>0,
 'capture_immutable_identity',exists(select 1 from pg_constraint where conrelid='public.life_naver_captures'::regclass and contype='u' and pg_get_constraintdef(oid)='UNIQUE (owner_id, blog_id, log_no, capture_hash)'),
 'runtime_disabled',not coalesce((select ready from haedo_naver_private.runtime where singleton),true)
);
